// Minimal server-side CKAN client — plain fetch, no dependency, no React coupling.
// Generated by /portaljs-connect-ckan. Used ONLY at build time (scripts/fetch-catalog.ts),
// so it never reaches the browser bundle.

// CKAN backend base URL. Override at build time with the DMS env var.
export const DMS = (process.env.DMS || 'https://api.old.datahub.io').replace(/\/+$/, '')

// Filters baked in by /portaljs-connect-ckan. Empty array = no filter.
export const ORG_FILTER: string[] = []
export const GROUP_FILTER: string[] = []

// Max datasets to pre-render at build time (SSG). 0 = the whole catalog. Set MAX_DATASETS
// in the environment for a quick dev build (e.g. MAX_DATASETS=300 npm run build).
export const MAX_DATASETS = Number(process.env.MAX_DATASETS || 0)

// CKAN caps package_search rows at 1000.
const PAGE_SIZE = 1000

// CKAN REST shapes — only the fields the portal reads.
export type CkanResource = {
  id: string
  name?: string
  description?: string
  format?: string
  url?: string
  size?: number | null
  last_modified?: string | null
  created?: string | null
}
export type CkanOrganization = { name?: string; title?: string }
export type CkanTag = { name: string; display_name?: string }
export type CkanPackage = {
  id: string
  name: string
  title?: string
  notes?: string
  url?: string
  version?: string
  author?: string
  maintainer?: string
  license_id?: string
  license_title?: string
  license_url?: string
  metadata_created?: string
  metadata_modified?: string
  organization?: CkanOrganization | null
  groups?: { name: string; title?: string }[]
  tags?: CkanTag[]
  resources?: CkanResource[]
}

export type SearchArgs = {
  offset?: number
  limit?: number
  tags?: string[]
  orgs?: string[]
  groups?: string[]
}

// Build a CKAN `fq` filter-query from org/group/tag lists (OR within a field). Always
// restricted to the `dataset` type so harvest sources and other package types stay out.
function buildFq({ orgs = [], groups = [], tags = [] }: SearchArgs): string {
  const clause = (field: string, vals: string[]) =>
    vals.length ? `${field}:(${vals.map((v) => `"${v}"`).join(' OR ')})` : ''
  return ['+dataset_type:dataset', clause('organization', orgs), clause('groups', groups), clause('tags', tags)]
    .filter(Boolean)
    .join(' ')
}

async function ckanAction(action: string, params: Record<string, string>, attempt = 1): Promise<any> {
  const qs = new URLSearchParams(params).toString()
  const res = await fetch(`${DMS}/api/3/action/${action}?${qs}`, { headers: { 'User-Agent': 'portaljs-build' } })
  if (!res.ok) {
    if (attempt < 4 && res.status >= 500) {
      await new Promise((r) => setTimeout(r, 2000 * attempt))
      return ckanAction(action, params, attempt + 1)
    }
    throw new Error(`CKAN ${action} failed: ${res.status} ${res.statusText}`)
  }
  const body = await res.json()
  if (!body?.success) throw new Error(`CKAN ${action} returned success=false`)
  return body.result
}

export const ckan = {
  async packageSearch(args: SearchArgs = {}): Promise<{ datasets: CkanPackage[]; count: number }> {
    const params: Record<string, string> = {
      start: String(args.offset ?? 0),
      rows: String(Math.min(args.limit ?? PAGE_SIZE, PAGE_SIZE)),
      // A stable sort so paging never skips or repeats a dataset.
      sort: 'name asc',
      fq: buildFq(args),
    }
    const result = await ckanAction('package_search', params)
    return { datasets: result.results ?? [], count: result.count ?? 0 }
  },

  // The whole (filtered) catalog, paging package_search 1000 at a time: ~12 requests for
  // 11.4k datasets instead of one package_show per dataset. package_search returns full
  // package dicts, resources included.
  async allDatasets(args: Omit<SearchArgs, 'offset' | 'limit'> = {}): Promise<{ datasets: CkanPackage[]; count: number }> {
    const out: CkanPackage[] = []
    let count = 0
    for (let offset = 0; ; offset += PAGE_SIZE) {
      const page = await ckan.packageSearch({ ...args, offset, limit: PAGE_SIZE })
      count = page.count
      out.push(...page.datasets)
      if (page.datasets.length < PAGE_SIZE || (MAX_DATASETS && out.length >= MAX_DATASETS)) break
    }
    return { datasets: MAX_DATASETS ? out.slice(0, MAX_DATASETS) : out, count }
  },

  async getDatasetDetails(slug: string): Promise<CkanPackage> {
    return ckanAction('package_show', { id: slug })
  },
}
